-- Seed the Kenyan CBC catalogue from current KICD regular curriculum guidance
-- and retain 8-4-4 as a clearly labelled legacy catalogue for historic content.
-- This migration only adds missing catalogue rows; it never replaces admin edits.
--
-- Primary KICD references:
-- https://kicd.ac.ke/wp-content/uploads/2026/09/COMPLEMENTARY-MATERIALS-SUBMISSION-DOCUMENT-SEPTEMBER-2026.pdf
-- https://kicd.ac.ke/cbc-materials/curriculum-designs/regular-curriculum-designs/
-- https://kicd.ac.ke/cbc-materials/curriculum-designs/junior-school-designs/
-- https://kicd.ac.ke/cbc-materials/curriculum-designs/senior-school-designs/
-- https://kicd.ac.ke/cbc-materials/pre-primary/
-- Legacy secondary subject names/codes cross-referenced against current KNEC KCSE
-- regulations: https://knec.ac.ke/wp-content/uploads/2026/01/KCSE_Regulations_2024.pdf
-- The application schema has no pathway field. Senior subjects are therefore
-- catalogued as grade-level design options; school subject/pathway selection is
-- not inferred by this seed.

INSERT INTO academic_curricula(code,name,description)
VALUES
 ('KE-CBC','Kenya CBC / CBE','Current Kenyan Competency-Based Curriculum catalogue. KICD 2026 complementary-material guidance lists the learning areas; senior school pathway choices are configured separately by each school.'),
 ('KE-844','Kenya 8-4-4 (legacy)','Legacy Kenyan curriculum catalogue for historic papers and records. KNEC states the 8-4-4 system is being phased out; retain only where needed to classify legacy material.')
ON CONFLICT(code) DO NOTHING;

WITH level_seed(curriculum_code,name,sort_order) AS (VALUES
 ('KE-CBC','Early Years Education',1),('KE-CBC','Primary School',2),('KE-CBC','Junior School',3),('KE-CBC','Senior School',4),
 ('KE-844','Primary School',1),('KE-844','Secondary School',2)
)
INSERT INTO academic_levels(curriculum_id,name,sort_order)
SELECT c.id,s.name,s.sort_order FROM level_seed s JOIN academic_curricula c ON c.code=s.curriculum_code
ON CONFLICT(curriculum_id,name) DO NOTHING;

WITH grade_seed(curriculum_code,level_name,name,sort_order) AS (VALUES
 ('KE-CBC','Early Years Education','PP1',1),('KE-CBC','Early Years Education','PP2',2),
 ('KE-CBC','Primary School','Grade 1',1),('KE-CBC','Primary School','Grade 2',2),('KE-CBC','Primary School','Grade 3',3),('KE-CBC','Primary School','Grade 4',4),('KE-CBC','Primary School','Grade 5',5),('KE-CBC','Primary School','Grade 6',6),
 ('KE-CBC','Junior School','Grade 7',1),('KE-CBC','Junior School','Grade 8',2),('KE-CBC','Junior School','Grade 9',3),
 ('KE-CBC','Senior School','Grade 10',1),('KE-CBC','Senior School','Grade 11',2),('KE-CBC','Senior School','Grade 12',3),
 ('KE-844','Primary School','Standard 1',1),('KE-844','Primary School','Standard 2',2),('KE-844','Primary School','Standard 3',3),('KE-844','Primary School','Standard 4',4),('KE-844','Primary School','Standard 5',5),('KE-844','Primary School','Standard 6',6),('KE-844','Primary School','Standard 7',7),('KE-844','Primary School','Standard 8',8),
 ('KE-844','Secondary School','Form 1',1),('KE-844','Secondary School','Form 2',2),('KE-844','Secondary School','Form 3',3),('KE-844','Secondary School','Form 4',4)
)
INSERT INTO academic_grades(level_id,name,sort_order)
SELECT l.id,g.name,g.sort_order FROM grade_seed g JOIN academic_curricula c ON c.code=g.curriculum_code
JOIN academic_levels l ON l.curriculum_id=c.id AND l.name=g.level_name
ON CONFLICT(level_id,name) DO NOTHING;

