INSERT INTO academic_grade_subjects(grade_id,subject_id)
SELECT g.id,s.id FROM grade_subjects x JOIN academic_curricula c ON c.code=x.curriculum_code
JOIN academic_levels l ON l.curriculum_id=c.id JOIN academic_grades g ON g.level_id=l.id AND g.name=x.grade_name
JOIN academic_subjects s ON s.curriculum_id=c.id AND s.name=x.subject_name
ON CONFLICT(grade_id,subject_id) DO NOTHING;

-- Term labels are configurable school calendar periods, not a KICD-mandated
-- national term schedule. Seed the common three-period pattern for convenience.
WITH term_seed(curriculum_code,name,sort_order) AS (VALUES
 ('KE-CBC','Term 1',1),('KE-CBC','Term 2',2),('KE-CBC','Term 3',3),
 ('KE-844','Term 1',1),('KE-844','Term 2',2),('KE-844','Term 3',3)
)
INSERT INTO academic_terms(curriculum_id,name,sort_order)
SELECT c.id,t.name,t.sort_order FROM term_seed t JOIN academic_curricula c ON c.code=t.curriculum_code
ON CONFLICT(curriculum_id,name) DO NOTHING;
